/**
 * The sortable domain vocabulary: the collection model, the insertion, the
 * proposal, the consumer resolution, and the terminal results.
 *
 * The public unions here are narrowed, with string discriminants:
 * discriminating a result must not require importing an internal outcome
 * constant.
 *
 * The numeric `recovery` constants below are the opposite: they are
 * behavior-private frame state, never handed to a consumer.
 */
import type { CancelOrigin, CancelStage } from '../kernel/failures.ts';

// ---------------------------------------------------------------------------
// The collection
// ---------------------------------------------------------------------------

/** An immutable ordered snapshot of the collection, and its version. */
export type CollectionSnapshot = Readonly<{
  items: readonly HTMLElement[];
  version: number;
}>;

/**
 * A proposed insertion gap in the **destination view** — the snapshot minus the
 * dragged item.
 *
 * `before` and `after` are real identity neighbours, not just an index: they
 * are what a reconciliation tests for survival, and what lets a start gap be
 * expressed at all.
 */
export type Insertion = Readonly<{
  version: number;
  index: number;
  before: HTMLElement | null;
  after: HTMLElement | null;
}>;

/**
 * **The construction rule for an {@link Insertion}**: the gap at `index` of
 * `destination` — a snapshot minus its dragged item — carrying the two elements
 * that gap sits between, in `snapshot`.
 *
 * **`index` is a gap position in `destination`, `0 .. destination.length`**:
 * `0` is before the first element, `destination.length` is after the last. This
 * **derives and does not validate** — `insertionAt(view, 999, snapshot)`
 * returns an insertion carrying `999` and `null` at both ends, and nothing
 * downstream checks either.
 *
 * `null` at both ends *is* the rule rather than a convenience: a read off
 * either end of the destination view is a **start** or an **end** gap, and
 * those two shapes are what a placeholder anchors on.
 *
 * **The version comes from the snapshot the gap is a gap of**, rather than as a
 * bare number, so a stale version is not a value a caller can supply.
 *
 * **A pure helper.** It takes an array and an index, holds no state and needs
 * no instant, so a caller passes whichever destination view it already holds.
 * The destination view is a **parameter** because deriving it here would
 * allocate an array per spatial resolution, on a pointer-move path that exists
 * to avoid exactly that.
 */
export function insertionAt(
  destination: readonly HTMLElement[],
  index: number,
  snapshot: CollectionSnapshot,
): Insertion {
  return {
    version: snapshot.version,
    index,
    before: destination[index - 1] ?? null,
    after: destination[index] ?? null,
  };
}

// ---------------------------------------------------------------------------
// The proposal
// ---------------------------------------------------------------------------

/** A proposed reorder, carrying both indices and stable neighbour identity. */
export type ReorderRequest = Readonly<{
  item: HTMLElement;
  version: number;
  from: number;
  to: number;
  before: HTMLElement | null;
  after: HTMLElement | null;
}>;

/**
 * Exactly one immutable proposal per operation, built after motion is closed.
 * It carries the snapshot it was computed against, so a consumer can reason
 * about the ordering the request refers to.
 */
export type ReorderProposal = Readonly<{
  snapshot: CollectionSnapshot;
  request: ReorderRequest;
}>;

// ---------------------------------------------------------------------------
// The consumer resolution
// ---------------------------------------------------------------------------

// Erased: `declare const` emits no JavaScript, and no value carries the key. It
// exists to keep the shape below unwritable by anything but the factories, and
// distinct from the other behavior's resolution, which is otherwise the same
// two words and the same representation.
declare const RESOLUTION: unique symbol;

/**
 * The explicit consumer response. **Acceptance is never inferred** — not from
 * callback silence, not from DOM mutation, not from collection order, not from
 * elapsed time. Neither is rejection.
 *
 * **Opaque, and a round trip rather than a record.** It is built by
 * {@link ReorderResolution.accept} or {@link ReorderResolution.reject},
 * returned from `onReorder`, and read only by the library; the verdict reaches
 * the consumer again as a `ReorderTransactionResult`, which is the shape with
 * the fields on it. Nothing here is inspectable and nothing here needs to be.
 */
export type ReorderResolution = Readonly<{ [RESOLUTION]: never }>;

/**
 * The two representations, **declared as what they are**: a resolution that is
 * also a tuple. The intersection is what lets the read side name an arm and
 * index it — `settlement.prepare` asserts to `RejectedResolution` and reads
 * slot 0, with no widening through `unknown` on the way.
 *
 * Neither is named outside this package: the entry publishes
 * {@link ReorderResolution} alone, which is the whole of the opacity.
 */
export type AcceptedResolution = ReorderResolution & readonly [];
export type RejectedResolution = ReorderResolution &
  readonly [reason?: unknown];

/**
 * Acceptance is a **shared value** — it declares nothing, so there is one of it
 * for the life of the module and an accepted reorder allocates nothing at all.
 * Rejection is the same carrier with the reason in it, and the only arm that
 * has to be built.
 *
 * **Identity is the discriminant**, which is why the empty carrier is a
 * constant rather than a fresh one per acceptance: there is no string to ship,
 * none to compare, and nothing on the value for a consumer to read or forge.
 *
 * **The two assertions below are irreducible and are the only ones.** The brand
 * is a *required* property no runtime value carries — that is what makes the
 * type unforgeable, and it is also why an array literal is not comparable to
 * it. `as never` is the narrowest spelling: it claims nothing about the source,
 * and the annotation beside it is what states the result.
 */
export const ACCEPTED: AcceptedResolution = [] as never;

/**
 * The two resolutions a consumer returns from `onReorder`. Acceptance declares
 * nothing: a consumer that must render before the drop lands `await`s its own
 * commit inside `onReorder`, which is what a promise-returning resolver already
 * expresses.
 */
export const ReorderResolution = {
  accept: (): ReorderResolution => ACCEPTED,
  reject: (reason?: unknown): ReorderResolution => [reason] as never,
} as const;

/**
 * The consumer's verdict on one proposed reorder.
 *
 * `PromiseLike`, not `Promise`: the returned value's `then` is read exactly
 * once, and a native promise is never assumed.
 */
export type OnReorder = (
  request: ReorderRequest,
  context: Readonly<{ signal: AbortSignal }>,
) => ReorderResolution | PromiseLike<ReorderResolution>;

// ---------------------------------------------------------------------------
// The terminal results
// ---------------------------------------------------------------------------

export type AcceptedReorderResult = Readonly<{
  type: 'accepted';
  proposal: ReorderProposal;
}>;

export type NoopReorderResult = Readonly<{
  type: 'noop';
  proposal: ReorderProposal;
}>;

export type RejectedReorderResult = Readonly<{
  type: 'rejected';
  reason: unknown;
  proposal: ReorderProposal;
}>;

export type CanceledReorderResult = Readonly<{
  type: 'canceled';
  /**
   * **What the decider had to say, and nothing more.** An open channel: a value
   * the consumer passed to `cancel`, one of the two constants this module
   * publishes, the value a classified failure threw, or `undefined`. Provenance
   * is `origin`, which the consumer cannot write; comparing `reason` to a
   * constant answers *what was said*, never *who said it*.
   */
  reason: unknown;
  /** Who decided, and of what kind. Written by the library. */
  origin: CancelOrigin;
  stage: CancelStage;
  /** Null when the operation was abandoned before a proposal existed. */
  proposal: ReorderProposal | null;
}>;

export type ReorderTransactionResult =
  | AcceptedReorderResult
  | NoopReorderResult
  | RejectedReorderResult
  | CanceledReorderResult;

// ---------------------------------------------------------------------------
// Behavior-private frame state
// ---------------------------------------------------------------------------

/**
 * Where the lifted visual goes, which is **not** the same question as whether
 * the authored presentation is final (`authoredReady`). Only a destination
 * recovery re-anchors: home deliberately returns the placeholder to the grab
 * slot, and immediate deliberately leaves it where it stands.
 */
export const RECOVERY_DESTINATION = 90;
export const RECOVERY_HOME = 91;
export const RECOVERY_IMMEDIATE = 92;

/** Why the behavior cancelled an operation of its own accord. */
export const CANCEL_COLLECTION_INVALIDATED = 'sortable:collection-invalidated';
export const CANCEL_ITEM_REMOVED = 'sortable:item-removed';
/**
 * The packed destination-slot geometry cache, shared by every axis feature.
 *
 * **Dimension-neutral, deliberately.** It packs both centres and both edges and
 * expresses no rule about which of them matters — that is the axis feature's,
 * and stays in the axis feature's own module. Extracting this is what lets
 * `y()` and `xy()` be two *rules* rather than two implementations of a cache,
 * without either of them growing a branch about the other.
 *
 * One `Float64Array` plus one parallel element array, indexed by
 * **destination** position — the collection minus the dragged item — so a slot
 * *is* the index the resulting `Insertion` needs and its neighbours are the
 * adjacent elements.
 *
 * Each axis feature holds its own instance, created inside its factory, so the
 * "where does the geometry cache live" question stays answered by construction:
 * nobody else can name it, reach it, or type it.
 */
import type { CollectionSnapshot } from './domain.ts';

/** Packed `[left, top, right, bottom, centreX, centreY]` per destination slot. */
export const STRIDE = 6;
export const LEFT = 0;
export const TOP = 1;
export const RIGHT = 2;
export const BOTTOM = 3;
export const CENTRE_X = 4;
export const CENTRE_Y = 5;

/**
 * **Fields, not accessors.** Exposing `values()` and `count()` as methods costs
 * 90 B on the minimal composition and two calls per resolution on the hot path
 * — for encapsulation nothing can observe, since the whole record is private to
 * one feature instance.
 */
export type RectIndex = {
  /** The packed values. Re-allocated only when the collection outgrows it. */
  values: Float64Array;
  /** Destination-ordered elements, parallel to the packed slots. */
  items: HTMLElement[];
  /** How many destination slots the last scan produced. */
  count: number;
  /**
   * Re-measures only when something dirtied the cache or the collection version
   * moved. On a frame where the pointer merely travels inside the same slot
   * this reads no geometry at all and the previous scan stands.
   *
   * The parameter is the installed `box` slot — already defaulted to `visual`
   * by the assembler — or `null` when the config named neither, in which case
   * every candidate *is* its own box and the resolver would be an identity call
   * per item per rebuild.
   *
   * `live` reports whether the controller is still alive. It is read **between
   * every consumer-reachable call in the traversal**, including the candidate's
   * own `getBoundingClientRect()`: the candidate is a consumer-owned element
   * and an overridden `getBoundingClientRect()` is a consumer call, not a
   * layout read. So a composition with **no** resolver reads it too — there the
   * item is its own box and the geometry read is the only consumer call in the
   * loop, but it is still one.
   *
   * Returns `false` — and **only** then — when the rebuild aborted on the
   * terminal barrier. The caller owes the same discipline for its own reads: it
   * must invoke no further consumer code, which includes measuring the
   * consumer-owned placeholder, whose `getBoundingClientRect()` a consumer may
   * have overridden. One shared channel rather than a per-axis `live()`
   * recheck: the recheck would cost a call per resolution in *every*
   * composition, where this costs one per candidate per **rebuild** only.
   */
  refresh(
    snapshot: CollectionSnapshot,
    dragged: HTMLElement,
    getBox: ((item: HTMLElement) => HTMLElement) | null,
    live: () => boolean,
  ): boolean;
  invalidate(): void;
  retire(): void;
};

const capacityFor = (needed: number): number => {
  let capacity = 1;

  while (capacity < needed) {
    capacity *= 2;
  }

  return capacity;
};

export function createRectIndex(): RectIndex {
  let capacity = 0;
  // Starts stale, and at a version no real collection can hold, so the first
  // resolution of every operation measures.
  let dirty = true;
  let measured = -1;

  // Declared before the record so the shared terminal exit below can name it:
  // the exit restores the retired state and reports the abort, and one
  // definition of "stop" is what keeps the four barriers in `refresh` from
  // drifting.
  let index: RectIndex;
  /**
   * **Not a `break`.** `destroy()` has already run `retire()` on this very
   * cache through the assembler's retire hooks, and falling through to
   * `refresh`'s trailing bookkeeping would write `count = n`,
   * `items.length = n`, `measured = version`, `dirty = false` — resurrecting a
   * retired cache, marking it clean, and pinning every row of the list in a
   * destroyed controller.
   *
   * **And the abort is reported**, because emptying the cache is not enough on
   * its own: `count === 0` makes the candidate scan find nothing, but both axes
   * measure the consumer-owned *placeholder* before that scan.
   */
  const abort = (): boolean => {
    index.retire();

    return false;
  };

  index = {
    values: new Float64Array(0),
    items: [],
    count: 0,

    refresh(snapshot, dragged, getBox, live): boolean {
      // A warm cache reads no geometry and calls no resolver, so it needs no
      // barrier — and it cannot be reached on a destroyed controller anyway:
      // `retire()` sets `dirty`, and teardown always runs it.
      if (!dirty && measured === snapshot.version) {
        return true;
      }

      // **The entry barrier.** A caller can reach a *dirty* cache with the
      // controller already closed: `settleDisplacement` runs the `beforeMove`
      // hooks — which measure consumer-owned rows — and `release.prepare`
      // resolves straight afterwards. Without this the first `getBox` of that
      // rebuild would be a consumer call after `destroy()` returned.
      if (!live()) {
        return abort();
      }

      const list = snapshot.items;

      // **One decision about one resource, driven by one number.** Growth and
      // shrink are the same question — is this buffer the right size for the
      // collection about to be scanned — so they are one branch rather than
      // two. It sits here, after the warm return and the entry barrier, because
      // `refresh` holds the real `list.length`: `retire()` would have to
      // **predict** the next operation's need from the last one's, and a policy
      // that needs no prediction needs no state that can go stale.
      //
      // **Nothing in the buffer is live at this instant.** The warm path
      // returned above, so the cache is dirty, and the scan below rewrites
      // every slot. A timer or an idle hook is refused by construction rather
      // than by preference: releasing a *correctly sized* buffer on elapsed
      // time makes a deterministic cache timing-dependent and needs a policy
      // input this library has no basis to own.
      //
      // **`capacity > 4 * n` is a consequence, not a tuning choice.**
      // `capacityFor` makes `n ≤ capacity < 2n` for any fitted buffer, so
      // `capacity > 2 * n` is already unreachable without a real collection
      // shrink; `4×` is one doubling looser, the cheapest hysteresis available,
      // and it keeps a collection wobbling around a power-of-two boundary from
      // resizing. A shrink therefore always allocates strictly less than it
      // frees, which is what separates this from a memory-for-allocations trade
      // — and exact-fit shrinking is refused for the same reason, since it
      // would recover a fitted buffer's legitimate slack and pay with a
      // reallocation on every single-item growth.
      if (list.length > capacity || capacity > 4 * list.length) {
        const fitted = capacityFor(list.length);

        // **The settle guard, and it earns its line at exactly one size.** For
        // any `n ≥ 1` a firing gate implies `fitted < capacity`, so this is
        // true by construction. At `n === 0` it is not: the gate reads
        // `capacity > 0`, which the one-slot buffer a previous empty refresh
        // just produced also satisfies — so without this an empty collection
        // reallocates 48 B on every scan instead of settling.
        if (fitted !== capacity) {
          capacity = fitted;
          index.values = new Float64Array(capacity * STRIDE);
        }
      }

      const { values, items } = index;
      let n = 0;

      for (const item of list) {
        if (item === dragged) {
          continue;
        }

        // The **box**, not the item and not the visual. The incumbent this
        // geometry is compared against is the placeholder, which is sized from
        // the box's removed footprint (`placement.ts`) — so the box is what
        // puts both sides of the comparison on one kind of rect. Measuring
        // items here, or visuals, would bias the hysteresis by the whole
        // distance between the two for any box that is not also the lifted
        // node. Under the default `box === visual` they coincide.
        let box = item;

        if (getBox) {
          box = getBox(item);

          // **The resolver barrier**, inside the branch because with no
          // resolver composed there is no call here for it to stand behind.
          if (!live()) {
            return abort();
          }
        }

        // **The geometry barrier**, covering indirect invocation, and it is
        // *outside* the branch: `box` is a consumer-owned element in every
        // composition — with no resolver composed the candidate item is its own
        // box — so an overridden `getBoundingClientRect()` is consumer code the
        // loop just ran. Everything after this line is a publication into the
        // cache, and the next iteration is another consumer call, so the
        // reading is taken before either.
        const rect = box.getBoundingClientRect();

        if (!live()) {
          return abort();
        }

        const offset = n * STRIDE;

        values[offset + LEFT] = rect.left;
        values[offset + TOP] = rect.top;
        values[offset + RIGHT] = rect.right;
        values[offset + BOTTOM] = rect.bottom;
        values[offset + CENTRE_X] = (rect.left + rect.right) * 0.5;
        values[offset + CENTRE_Y] = (rect.top + rect.bottom) * 0.5;
        items[n] = item;
        n += 1;
      }

      index.count = n;
      // Truncated, so a shrinking collection neither pins the elements a larger
      // previous rebuild saw nor leaks one into a neighbour lookup.
      items.length = n;
      measured = snapshot.version;
      dirty = false;

      return true;
    },

    /**
     * The behavior owns the events that make geometry stale — activation,
     * scroll, resize, a committed placeholder move, collection publication,
     * release — and the feature owns the cache. One flag, because any single
     * reason forces the same full rebuild.
     */
    invalidate(): void {
      dirty = true;
    },

    /**
     * The element array is what pins DOM between operations, so it is emptied;
     * the numeric buffer is kept and reused. Also what `abort()` above calls.
     */
    retire(): void {
      index.items.length = 0;
      index.count = 0;
      dirty = true;
      measured = -1;
    },
  };

  return index;
}
/**
 * The **verified** incremental refresh: a wrapper around
 * {@link createRectIndex} rather than a branch inside it.
 *
 * A committed placeholder move from gap `A` to gap `B` should change only the
 * rows in `[min, max)`, each by the same scalar `δ`. That is a *hypothesis*,
 * not tracked state: the previous gap is this module's own record and can
 * silently disagree with the DOM, so it never gets to be right on its own. It
 * proposes a span, four reads check the proposal, and any refutation falls
 * through to the full rebuild — in the same window, exactly where it runs
 * today.
 *
 * **Why it is a module and not a branch.** The fast path is `y()`-only *by
 * contract* — `xy()` wraps, so `δ` is neither scalar nor uniform — and code
 * that only one feature may ever execute belongs in that feature's module
 * graph, which is the rule every other optional feature in this package is held
 * to. Folded into the shared cache it costs an `xy()` composition **+135 B** of
 * machinery that composition can never reach. `bench/size` asserts the absence.
 *
 * **`RectIndex` is untouched by this file's existence.** It stays
 * dimension-neutral, it keeps the full scan, and it gained **no hook**: this
 * module wraps it, mirrors the two state bits it would otherwise have had to
 * expose (`dirty`, and the version the buffer holds), and mutates the packed
 * values through the fields the record already publishes. A cache that has to
 * know about the optimization is a cache the optimization has re-coupled.
 */
import type { CollectionSnapshot } from './domain.ts';
import {
  BOTTOM,
  CENTRE_X,
  CENTRE_Y,
  LEFT,
  type RectIndex,
  RIGHT,
  STRIDE,
  TOP,
} from './rect-index.ts';

/**
 * The development-build flag, read as the **bare global**.
 *
 * `__DEV__` is declared in `src/globals.d.ts` at **package** scope, so it is
 * package vocabulary rather than kernel vocabulary and the behavior tier binds
 * it directly. The kernel binds the ambient nowhere at all, and importing such
 * a binding would assert a behavior-tier reach into `kernel/` that must not
 * exist. The substitution and the folding are identical either way: `__DEV__`
 * is replaced at build time, `DEV` is a literal, and every branch guarded by it
 * is dead code the minifier drops.
 *
 * **This is the package's one binding**, and
 * `tests/kernel/vocabulary.node.test.ts` asserts that — one per tier, and
 * `__DEV__` read at no other site. A second dev assertion in a second module of
 * this tier is the trigger for a tier-local `sortable/dev.ts`, which would
 * still import nothing from `kernel/`.
 */
const DEV: boolean = __DEV__;

/**
 * The re-synchronisation interval `k`: a **full** rebuild every `k` committed
 * moves, however well the verification is going.
 *
 * It is not a tuning constant — it bounds how long a drift the verification
 * cannot see can persist, because verification cannot see a `transform` applied
 * to a single **strictly interior** row: one that is neither end of the span,
 * so neither in-span witness reads it. At spans of 1 or 2 there is no such row
 * and no exposure at all, and one row is exactly what the general rebuild would
 * have got wrong too.
 *
 * **What it does *not* do is cap the payoff at `k×`.** `k×` is a ceiling that
 * would bind only if a verified move cost approximately nothing; it costs ≈1.0
 * ms of the general path's 3.5 ms at 800 rows, because the rebuild's dominant
 * term in the deployed regime is the **forced layout after the placeholder
 * write** and not the per-row reads. The binding ceiling is `full / verified` ≈
 * 3.5×, and `k` only decides how close the mean lands: `k = 8` measures 2.67×,
 * 76% of what is achievable, against ~12% more for `k = 16` and ~24% less for
 * `k = 4`. **So raising it buys little and spends drift tolerance for it**, and
 * no measured payoff supports a larger `k`.
 */
export const RESYNC_INTERVAL = 8;

/**
 * Whether the equivalence instrument runs. `DEV`-only in every sense: the read
 * sits inside a `DEV` branch, so the published bundle contains neither it nor
 * this binding.
 *
 * **It is not a measurement flag, and the direction is the whole of why.** The
 * instrument is on by default and every suite run checks it; this exists for
 * the opposite case — a performance measurement, which has to measure the code
 * that *ships*. The instrument performs the full scan it compares against, so
 * leaving it on would time the general path and the fast path together and
 * report a number that exists in no build a consumer can install. A measurement
 * that turns it off is measuring the product; a suite that turned it off would
 * be measuring nothing, and nothing else may call this.
 */
let verifying = true;

/** @see verifying — used by `tests/perf`, and by nothing in `src`. */
export function setRefreshVerification(enabled: boolean): void {
  if (DEV) {
    verifying = enabled;
  }
}

export type VerifiedRefresh = Readonly<{
  /**
   * {@link RectIndex.refresh} with one argument added: `gap`, the **committed
   * destination gap of the placeholder move this call is servicing**, or `-1`
   * for every other caller.
   *
   * It is two things at once, deliberately. It is the *reason signal* —
   * `measure()` has exactly one call site, the committed-move bracket, so being
   * called with a gap at all is what says a placeholder move just happened,
   * with no widening of `invalidateInsertion` and no reason argument anywhere.
   * And it is one half of the **span hypothesis**, paired with the gap this
   * cache last serviced.
   */
  refresh(
    snapshot: CollectionSnapshot,
    dragged: HTMLElement,
    getBox: ((item: HTMLElement) => HTMLElement) | null,
    live: () => boolean,
    gap: number,
  ): boolean;
  invalidate(): void;
  retire(): void;
}>;

// The three outcomes of an attempted incremental refresh. `REFUSED` is not an
// error and is not reported: it is the ordinary path, taken for a frame,
// exactly where the full rebuild runs today.
const REFUSED = 0;
const APPLIED = 1;
const ABORTED = 2;

/**
 * The sentinel {@link translation} returns when the controller died inside its
 * read. `Infinity` rather than a fourth constant because a `δ` is a difference
 * of two viewport scalars and can never be one.
 */
const DEAD = Infinity;

/**
 * One witness read: **is this row exactly where the cache says it is?**
 *
 * `1` unchanged, `0` moved, `-1` the controller died inside the read. The read
 * is an indirect consumer call — the row is a consumer-owned element and
 * `getBoundingClientRect()` may be overridden — so the liveness reading is
 * taken between it and everything after, exactly as the candidate loop does.
 * Four of these per committed move, against `n` for a full rebuild.
 *
 * All four edges are compared, not just the axis ones. The buffer is
 * dimension-neutral by construction and the equivalence instrument holds it to
 * a full scan on both axes, so a witness that ignored X would licence a write
 * the instrument then rejects.
 *
 * **It returns the outcome triple**, because a per-witness verdict *is* the
 * hypothesis's outcome so far: a witness that agrees leaves the span appliable,
 * one that disagrees refuses it, and one that dies inside its own read aborts.
 * Three of these run per committed move and the caller forwards the verdict
 * unchanged, so a mapping ternary at each site would say nothing the constants
 * do not.
 */
const unchanged = (
  index: RectIndex,
  i: number,
  live: () => boolean,
): number => {
  const rect = index.items[i]!.getBoundingClientRect();

  if (!live()) {
    return ABORTED;
  }

  const { values } = index;
  const offset = i * STRIDE;

  return values[offset + LEFT] === rect.left &&
    values[offset + TOP] === rect.top &&
    values[offset + RIGHT] === rect.right &&
    values[offset + BOTTOM] === rect.bottom
    ? APPLIED
    : REFUSED;
};

/**
 * **The equivalence instrument**, and the thing that makes the fast path
 * admissible rather than merely plausible.
 *
 * Whenever the incremental path runs, the packed buffer must equal what a full
 * scan of the same tree would have produced. That is asserted here, on every
 * suite run, and it is *not* behind any measurement flag: `DEV` is `true` in
 * this repository's vite and vitest configs and folds to `false` in the
 * published bundle, so every test that drives a real drag through `y()` checks
 * it and no consumer pays for it.
 *
 * **It heals before it throws.** The scan it performs to compare is the same
 * scan the full path would have run, so it writes the authoritative values back
 * as it goes and only then reports. A mismatch therefore leaves the cache
 * *correct* and the drag classified, rather than correct in the message and
 * wrong in the buffer.
 *
 * **It threads `live()` exactly as the candidate loop does.** Each
 * `getBoundingClientRect()` here is a consumer call on a consumer-owned
 * element, and a reading taken *before* this scan starts says nothing about the
 * `n` calls inside it — the reading belongs between them, exactly as it sits in
 * `RectIndex.refresh`. _It is `DEV`-only_ is not a waiver: this repository
 * builds `__DEV__` as `true`, so every in-repo fixture runs this path, and an
 * instrument that skipped the barrier would make the `DEV` build violate an
 * invariant the shipped build holds.
 *
 * **On abort it stops and reports nothing**, returning `false` for the caller
 * to retire on. Two reasons, and the second is the sharper: a partially
 * completed scan legitimately differs from the fast-path buffer, so comparing
 * one would turn a correct teardown into a spurious mismatch that blames the
 * span hypothesis for a destroy; and the trailing `count`/`length` bookkeeping
 * below is exactly what `RectIndex`'s own `abort()` refuses to run after a
 * retire, on the grounds that it resurrects a retired cache and pins every row
 * of the list in a destroyed controller.
 */
const verify = (
  index: RectIndex,
  snapshot: CollectionSnapshot,
  dragged: HTMLElement,
  live: () => boolean,
): boolean => {
  const { values, items } = index;
  let n = 0;
  let mismatch = '';

  for (const item of snapshot.items) {
    if (item === dragged) {
      continue;
    }

    const rect = item.getBoundingClientRect();

    if (!live()) {
      return false;
    }

    const offset = n * STRIDE;
    const centreX = (rect.left + rect.right) * 0.5;
    const centreY = (rect.top + rect.bottom) * 0.5;

    if (
      mismatch === '' &&
      (items[n] !== item ||
        values[offset + LEFT] !== rect.left ||
        values[offset + TOP] !== rect.top ||
        values[offset + RIGHT] !== rect.right ||
        values[offset + BOTTOM] !== rect.bottom ||
        values[offset + CENTRE_X] !== centreX ||
        values[offset + CENTRE_Y] !== centreY)
    ) {
      mismatch = `slot ${n}`;
    }

    values[offset + LEFT] = rect.left;
    values[offset + TOP] = rect.top;
    values[offset + RIGHT] = rect.right;
    values[offset + BOTTOM] = rect.bottom;
    values[offset + CENTRE_X] = centreX;
    values[offset + CENTRE_Y] = centreY;
    items[n] = item;
    n += 1;
  }

  if (mismatch === '' && n !== index.count) {
    mismatch = `count ${index.count}, full scan ${n}`;
  }

  index.count = n;
  items.length = n;

  if (mismatch !== '') {
    throw new Error(
      `drag: the incremental insertion refresh disagreed with a full scan at ${mismatch}; the span hypothesis does not hold for this list`,
    );
  }

  return true;
};

/**
 * The span hypothesis, verified in a constant number of reads.
 *
 * With the placeholder moved from gap `from` to gap `to`, the rows whose
 * geometry changed should be exactly `[lo, hi)`, each by the same scalar `δ`,
 * and nothing outside it. Four witnesses check that:
 *
 * - **the in-span witnesses**, rows `lo` and `hi − 1`, which *yield* `δ` —
 * measured, never modelled, which is what keeps margins, `gap` and box-sizing
 * out of this module entirely. A `δ` of zero refutes, and so does the two of
 * them disagreeing. The second is skipped when the span is one row, where they
 * would be the same row;
 * - **the after-witness**, row `hi`, must be unchanged;
 * - **the suffix witness**, row `count − 1`, must be unchanged. In a linear
 * flow any change to any row's contribution shifts every row below it, so flow
 * drift is suffix-shaped and this is what catches collapsing margins and scroll
 * anchoring;
 * - **the before-witness**, row `lo − 1`, when one exists.
 *
 * Nothing is written until all of them agree, so a refusal leaves the buffer
 * untouched for the full scan that follows.
 *
 * **The second in-span witness restores parity rather than buying a new
 * property.** With only row `lo` measured, a row carrying an unexpected offset
 * that *is* the witness makes `δ` wrong by that offset and the error is applied
 * to the whole span, while every other witness honestly agrees — up to
 * `hi − lo − 1` rows wrong for up to `k` moves, against the one row the general
 * path risks. The escape is narrow and that sharpens it: the four-quantity
 * comparison already catches horizontal movement and size change, so what
 * survives is a **pure vertical translation** — precisely the shape of a
 * running FLIP offset, which is enough on its own to corrupt a rebuild, and
 * which a third-party `beforeMove` releasing less than the first-party one
 * produces in this very window. Under the general path that corrupts one row;
 * under a single-witness fast path it corrupts the span. **This path is a
 * smaller rebuild in the same window, not a behaviourally different one**, so
 * the amplification would falsify that however rare the trigger.
 *
 * **What remains, and it is the acceptance criterion.** At spans of 1 or 2
 * there is no exposure at all — both ends are witnesses. At spans of 3 or more
 * exactly one strictly interior row can be wrong, for at most `k` moves, which
 * **equals the general path's exposure**. Span-wide corruption needs both
 * witnesses to carry an identical pure vertical offset in the same frame; that
 * is named and accepted, not guarded against.
 */
/**
 * The δ an in-span witness yields, or a refutation.
 *
 * A finite number is the measured translation; `NaN` means the row refutes the
 * hypothesis outright — it did not move, or it moved horizontally, or it
 * changed size — and {@link DEAD} means the controller died inside the read.
 * Encoded as three numbers rather than a record because this runs twice per
 * committed move and allocates nothing.
 *
 * The same four quantities the design names, and all four matter: `top` gives
 * `δ`, `bottom` proves the row translated rather than grew, and `left`/`right`
 * prove it did not travel across the axis the packed buffer also holds.
 */
const translation = (
  index: RectIndex,
  i: number,
  live: () => boolean,
): number => {
  const rect = index.items[i]!.getBoundingClientRect();

  if (!live()) {
    return DEAD;
  }

  const { values } = index;
  const offset = i * STRIDE;
  const delta = rect.top - values[offset + TOP]!;

  // The `bottom` test is written as "the cached bottom, shifted" rather than as
  // "the measured difference equals `δ`" — the same equation either way, and
  // the same exactness, since both sides are sums of viewport scalars the
  // engine produces as multiples of a layout unit.
  return delta !== 0 &&
    values[offset + BOTTOM] === rect.bottom - delta &&
    values[offset + LEFT] === rect.left &&
    values[offset + RIGHT] === rect.right
    ? delta
    : Number.NaN;
};

const shift = (
  index: RectIndex,
  from: number,
  to: number,
  live: () => boolean,
): number => {
  const { count } = index;
  const lo = from < to ? from : to;
  const hi = from < to ? to : from;

  // **The named degradation.** A span reaching the end of the list has neither
  // an after-witness nor a suffix witness outside it, so the hypothesis cannot
  // be checked at all. Dragging to the last slot pays the old cost, and that is
  // accepted rather than worked around.
  if (hi >= count) {
    return REFUSED;
  }

  const delta = translation(index, lo, live);

  if (delta === DEAD) {
    return ABORTED;
  }

  if (Number.isNaN(delta)) {
    return REFUSED;
  }

  // **The second in-span witness**, at the far end of the span and required to
  // agree on the same `δ`. Skipped for a one-row span, where it would be row
  // `lo` again and the blast radius is zero either way.
  //
  // The comparison is `!==` rather than a NaN test, because it has to decide
  // two things at once and one operator decides both: a refuted second witness
  // yields `NaN`, which is unequal to every `δ`, and an honest one that
  // disagrees is unequal too. Either way the span hypothesis is false.
  if (hi - lo > 1) {
    const second = translation(index, hi - 1, live);

    if (second === DEAD) {
      return ABORTED;
    }

    if (second !== delta) {
      return REFUSED;
    }
  }

  const after = unchanged(index, hi, live);

  if (after !== APPLIED) {
    return after;
  }

  const tail = count - 1;

  if (tail !== hi) {
    const suffix = unchanged(index, tail, live);

    if (suffix !== APPLIED) {
      return suffix;
    }
  }

  if (lo > 0) {
    const before = unchanged(index, lo - 1, live);

    if (before !== APPLIED) {
      return before;
    }
  }

  const { values } = index;

  for (let i = lo; i < hi; i += 1) {
    const offset = i * STRIDE;
    const top = values[offset + TOP]! + delta;
    const bottom = values[offset + BOTTOM]! + delta;

    values[offset + TOP] = top;
    values[offset + BOTTOM] = bottom;
    // Recomputed from the shifted edges rather than shifted itself, so the
    // arithmetic is the one the full scan performs and the equivalence
    // instrument compares like with like.
    values[offset + CENTRE_Y] = (top + bottom) * 0.5;
  }

  return APPLIED;
};

/**
 * Wraps one `RectIndex` in the verified fast path.
 *
 * **It mirrors rather than reaches.** The two bits the fast path needs from the
 * cache — is it clean, and which collection version does the buffer hold — are
 * derived here from the calls this wrapper already intercepts, so `RectIndex`
 * needs no accessor, no `settle()` and no residue of this module at all. The
 * mirror cannot drift: both bits are cleared by `invalidate()` and by
 * `retire()` and set by a successful refresh, and every one of those three
 * arrives through this object.
