  'border-right-style',
  'border-bottom-style',
  'border-left-style',
  'border-top-color',
  'border-right-color',
  'border-bottom-color',
  'border-left-color',
  'overflow-x',
  'overflow-y',
  'color',
  'background-color',
];

// ---------------------------------------------------------------------------
// InlineStyleLease
// ---------------------------------------------------------------------------

/**
 * Captures the inline lifted properties before the first write; restores once.
 *
 * Restoration is **per property, never the whole `style` attribute**. A drag is
 * a window in which the consumer's own code runs — `onStart`, the resolver, a
 * readiness promise — and it may legitimately write inline styles the lift
 * never touches. Rewriting the attribute wholesale would silently revert those;
 * this reverts exactly the declarations the lift is responsible for.
 */
export function captureInlineStyles(visual: HTMLElement): Disposer {
  const saved = new Map<string, readonly [string, string]>();

  for (const prop of LIFTED_PROPS) {
    const value = visual.style.getPropertyValue(prop);

    if (value) {
      saved.set(prop, [value, visual.style.getPropertyPriority(prop)]);
    }
  }

  let restored = false;

  return () => {
    if (restored) {
      return;
    }

    restored = true;

    for (const prop of LIFTED_PROPS) {
      const value = saved.get(prop);

      if (value) {
        visual.style.setProperty(prop, value[0], value[1]);
      } else {
        visual.style.removeProperty(prop);
      }
    }
  };
}

// ---------------------------------------------------------------------------
// TopLayerLease
// ---------------------------------------------------------------------------

/**
 * Enters and restores top-layer/popover state, remembering the prior state.
 *
 * **Transactional.** Promotion is two writes, not one: setting the `popover`
 * attribute, which by itself closes a popover the page had already opened, and
 * then `showPopover()`. Either can throw — `showPopover()` does whenever the
 * element is not in a state the UA will promote — and until this function
 * returns, its disposer does not exist, so nothing else in the package can
 * possibly restore what the first write already changed. So acquisition rolls
 * itself back and rethrows: it either fully owns the top layer or leaves the
 * element exactly as it found it.
 */
export function acquireTopLayer(visual: HTMLElement, unwind: Unwind): Disposer {
  const priorAttribute = visual.getAttribute('popover');
  const priorOpen = visual.matches(':popover-open');

  let disposed = false;

  // Built before the first mutation, so the rollback path and the disposer are
  // the same code against the same captured prior state.
  const restore = (): void => {
    if (disposed) {
      return;
    }

    disposed = true;

    if (visual.matches(':popover-open')) {
      visual.hidePopover();
    }

    if (priorAttribute == null) {
      visual.removeAttribute('popover');
    } else {
      visual.setAttribute('popover', priorAttribute);
    }

    if (priorOpen && visual.matches('[popover]')) {
      visual.showPopover();
    }
  };

  try {
    visual.popover = 'manual';

    if (!visual.matches(':popover-open')) {
      visual.showPopover();
    }
  } catch (error) {
    // Unwound rather than called, because the rollback re-enters the same
    // popover API that just failed and can therefore fail again — restoring a
    // previously-open popover is literally the call that threw. **The statement
    // after it is the load-bearing one**: the acquisition error is what
    // explains why the lift was refused, and it must still reach the caller.
    unwind(restore);
    throw error;
  }

  return restore;
}

// ---------------------------------------------------------------------------
// Shared lift helpers
// ---------------------------------------------------------------------------

function neutralizeUA(visual: HTMLElement, style: CSSStyleDeclaration): void {
  // Read every UA value up front, while the computed style is still clean.
  // Interleaving these reads with the writes below forces a style recalc per
  // property (each `setProperty` dirties the style the next `getPropertyValue`
  // must then flush); batching collapses that whole cluster into one recalc.
  const values = UA_PROPS.map((prop) => style.getPropertyValue(prop));

  visual.style.boxSizing = 'border-box';
  visual.style.margin = '0';

  for (let i = 0; i < UA_PROPS.length; i += 1) {
    visual.style.setProperty(UA_PROPS[i]!, values[i]!);
  }
}

// ---------------------------------------------------------------------------
// VisualLiftSession
// ---------------------------------------------------------------------------

/**
 * One visual's active presentation mode. Composes the inline-style lease and,
 * where applicable, the top-layer lease. It exposes only the transform
 * composition downstream movement and landing need, and never updates geometry,
 * animates, or invokes callbacks.
 */
export type VisualLiftSession = Readonly<{
  visual: HTMLElement;
  /** The authored/lift base transform the drag translation is composed with. */
  baseTransform: string;
  /**
   * The full transform string for a viewport delta.
   *
   * **Allocation-free in every mode.** The two lifted modes translate the
   * viewport delta directly; the in-place mode projects it through the inverse
   * of its inherited box space, which is four multiplies over scalars the
   * session captured at acquisition. Nothing on this path allocates except the
   * transform string itself.
   */
  compose(x: number, y: number): string;
  /**
   * **The delta `write` last composed and assigned** — where the visual *is*,
   * in the origin-relative viewport space `compose` and `write` consume.
   * `(0, 0)` until the first `write`, which is the truth for an operation that
   * never rendered and for a pointerless one.
   *
   * `LandingContext.from` is read from here rather than from the pointer: a
   * behavior that constrains, clamps, snaps or externally drives its visual
   * writes something other than the raw pointer delta, and a pointerless
   * operation has no pointer at all, so the pointer form would open the landing
   * from a position the visual has never been at.
   *
   * **Kernel-read.** The behavior is handed a {@link BehaviorLiftSession},
   * which does not carry this member.
   *
   * `compose` records nothing — composing is not rendering, and a landing
   * runner composes on every frame.
   */
  rendered: Point;
  /**
   * Composes a viewport delta and writes it to the visual's inline transform.
   *
   * This is how the kernel performs the **authoritative pin** at the join.
   * Correctness deliberately does not depend on the landing runner: the runner
   * drives the transform while it is alive, and the kernel re-measures and
   * writes the final position through the lift session it already owns, after
   * `LandingHandle.destroy()` has relinquished control.
   *
   * A throw here is classified `FAILURE_RENDERER_WRITE` by the caller.
   */
  write(x: number, y: number): void;
  dispose: Disposer;
}>;

/**
 * What a **behavior** is handed: the same physical session, positively
 * projected to the four members it may use.
 *
 * `rendered` and `dispose` are kernel-only. The session's lifetime is the
 * kernel's: disposing it from `activation.effect` or `moved` would drop the
 * inline-style lease — and, in a lifted mode, the top-layer lease — while the
 * recorded delta still describes the last `write`, so the landing would open
 * from a visual that is no longer lifted.
 *
 * The projection is type-level. The kernel passes the *same object* under the
 * narrower type, so it costs no allocation.
 *
 * **It does not project away the timing.** `write` stays callable and stays
 * *effective* — no phase test, no operation check — so calling it after
 * `LandingContext.from` has been sampled fights the landing runner for the same
 * property, and calling it after retirement writes onto an element no live
 * operation owns. Both are outside the contract and neither is refused.
 */
export type BehaviorLiftSession = Readonly<
  Pick<VisualLiftSession, 'visual' | 'baseTransform' | 'compose' | 'write'>
>;

/**
 * The inverse of an inherited linear part, or `null` for the identity, a
 * singular space or a non-finite one.
 *
 * `null` means **the local delta is the viewport delta** — the correct answer
 * for an untransformed ancestry and the honest one for a space that cannot be
 * inverted. It is also what lets `compose` skip the projection entirely on the
 * hot path.
 *
 * **The same shape serves two readers with two different values,
 * deliberately.** `ActivationScope.inheritedSpace` is a fact about the ancestry
 * at grab and is computed for every lift mode; the session's own projection is
 * the space an *in-place* translate acts in and is `null` for both lifted
 * modes, because a lifted visual is repositioned into the viewport. Conflating
 * them would hand a behavior the identity under `LIFT_FLAT`, wrong and silent.
 */
export type InheritedSpace = Readonly<{
  a: number;
  b: number;
  c: number;
  d: number;
}> | null;

function makeSession(
  visual: HTMLElement,
  baseTransform: string,
  projection: InheritedSpace,
  dispose: Disposer,
): VisualLiftSession {
  const suffix = baseTransform ? ` ${baseTransform}` : '';

  const compose = projection
    ? (x: number, y: number): string =>
        `translate(${projection.a * x + projection.c * y}px, ${
          projection.b * x + projection.d * y
        }px)${suffix}`
    : (x: number, y: number): string => `translate(${x}px, ${y}px)${suffix}`;

  // The recorded delta, mutable here and `Point` everywhere else. One object
  // per operation, written in place: recording costs these two field writes per
  // sample, where re-publishing a fresh `{ x, y }` would put an allocation on
  // the pointer-sample path, which is allocation-free.
  const rendered = { x: 0, y: 0 };

  return {
    visual,
    baseTransform,
    compose,
    rendered,
    write(x: number, y: number): void {
      // Recorded **after** the assignment, deliberately. A composition or style
      // write that throws is classified `FAILURE_RENDERER_WRITE` by the caller,
      // and the visual is then wherever it already was — so recording first
      // would leave the session claiming a delta the element never took, and
      // the landing would open from a position that only the record believes.
      visual.style.transform = compose(x, y);
      rendered.x = x;
      rendered.y = y;
    },
    dispose,
  };
}

/**
 * The inverse of the linear part the visual **inherits** — everything strictly
 * above it, its own transform and zoom excluded — or `null` when that space is
 * the identity or is unusable.
 *
 * **Two callers, one read.** It is the space an in-place translate acts in,
 * because an in-place lift *prepends* its translate to the visual's authored
 * transform, so the translate sits outside that transform and is scaled only by
 * what the visual inherits — inverting the visual's own space would divide its
 * scale out twice, and a `scale(2)` visual would move half as far as asked. It
 * is **also** the projection a behavior needs to report a local delta, and that
 * caller wants it under every lift mode rather than only in place. So it is
 * computed once here and published twice: to `compose` for the in-place mode
 * alone, and to `ActivationScope.inheritedSpace` always.
 *
 * The basis comes from the one traversal box-quad already performed, rather
 * than from `item.offsetParent` — which stops at a shadow boundary and is
 * `null` for a fixed-position visual — so every flat-tree, shadow-root and
 * `display: contents` rule stays in the package that owns them.
 */
function inheritedSpaceOf(measured: Box): InheritedSpace {
  const a = measured[BOX_ANCESTOR_A]!;
  const b = measured[BOX_ANCESTOR_B]!;
  const c = measured[BOX_ANCESTOR_C]!;
  const d = measured[BOX_ANCESTOR_D]!;

  if (a === 1 && b === 0 && c === 0 && d === 1) {
    // The common case. A null projection makes `compose` skip the arithmetic
    // entirely on the hot path.
    return null;
  }

  const determinant = a * d - b * c;

  if (determinant === 0 || !Number.isFinite(determinant)) {
    return null;
  }

  return {
    a: d / determinant,
    b: -b / determinant,
    c: -c / determinant,
    d: a / determinant,
  };
}

/**
 * What one acquisition produces: the session, and the pre-lift ancestry fact
 * derived from the same measurement.
 *
 * **Two products rather than one member on the session**, and the reason is
 * lifetime: every member of `VisualLiftSession` describes the state acquisition
 * *created*, while `inheritedSpace` describes the state it *destroyed*. Putting
 * it on the session would put a pre-lift fact inside the post-lift write
 * capability, next to a same-shaped projection holding a different value. The
 * kernel copies it onto `ActivationScope`, where the other pre-lift facts —
 * `originRect`, `boxPre` — already live.
 */
export type LiftAcquisition = Readonly<{
  session: VisualLiftSession;
  inheritedSpace: InheritedSpace;
}>;

/**
 * Acquires a lift.
 *
 * The visual's box space is read **once**, here: the composed element→viewport
 * matrix (the faithful mode's base transform), the untransformed border-box
 * size (both lifted modes' fixed box), the inherited zoom (which the top layer
 * does not escape, so a lifted visual divides it back out), the inverse used by
 * the in-place projection, and the inherited space the activation scope
 * publishes all come from that one traversal.
 *
 * **That "once" is load-bearing rather than merely efficient.** Everything
 * below this measurement mutates the visual — positioning, dimensions,
 * top-layer state, transforms — so a second traversal taken afterwards reads a
 * different ancestry, and box-quad's own contract says the two walks may
 * legitimately disagree. A behavior that measured for itself could therefore
 * lift on one coordinate snapshot and report consumer deltas from another.
 *
 * Throws when the space cannot be read — a disconnected or fragmented visual,
 * or a 3D transform this library does not model. The caller classifies it as
 * `FAILURE_ACTIVATION`; silently flattening 3D to its 2D projection would
 * produce a wrong lift rather than a refused one.
 *
 * Style capture and top-layer acquisition are composed into the returned
 * `dispose` in reverse acquisition order.
 */
export function acquireLift(
  visual: HTMLElement,
  mode: LiftMode,
  originRect: DOMRectReadOnly,
  realm: DOMRealm,
  unwind: Unwind,
): LiftAcquisition {
  const measured = box();

  if (!coordinates(visual, measured)) {
    // No readable box space: the visual is disconnected, fragmented across
    // lines, or inside a 3D-transformed subtree, so there is no single rect to
    // lift from.
    throw new Error('drag: presentation/visual-no-box-space');
  }

  // **Read before anything mutates, published for every mode.** The in-place
  // branch below hands the same value to `compose`; the lifted branches hand
  // `compose` the identity, because a lifted visual is repositioned into the
  // viewport, and still publish this one.
  const inheritedSpace = inheritedSpaceOf(measured);
  const width = measured[BOX_WIDTH]!;
  const height = measured[BOX_HEIGHT]!;
  const ancestorZoom = measured[BOX_ANCESTOR_ZOOM]!;
  const style = realm.window.getComputedStyle(visual);
  const styleLeaseDisposer = captureInlineStyles(visual);

  // Everything below mutates the visual. The style lease is already held, but
  // the *caller* only learns about it through the returned session — so a throw
  // from here on would leave the visual promoted and restyled with nothing that
  // could ever restore it. Acquisition is all-or-nothing.
  try {
    if (mode === LIFT_IN_PLACE) {
      // Stay in the container, ride the authored transform, and suppress
      // transitions so engine transform writes apply instantly.
      const own = style.transform;
      visual.style.transition = 'none';

      return {
        session: makeSession(
          visual,
          own === 'none' ? '' : own,
          inheritedSpace,
          styleLeaseDisposer,
        ),
        inheritedSpace,
      };
    }

    neutralizeUA(visual, style);
    visual.style.transition = 'none';
    visual.style.position = 'fixed';
    visual.style.inset = 'auto';
    visual.style.width = `${width}px`;
    visual.style.height = `${height}px`;

    let base = '';

    if (mode === LIFT_FAITHFUL) {
      const a = measured[BOX_A]!;
      const b = measured[BOX_B]!;
      const c = measured[BOX_C]!;
      const d = measured[BOX_D]!;

      base = `matrix(${a}, ${b}, ${c}, ${d}, ${measured[BOX_E]!}, ${measured[BOX_F]!})`;
      // Net zoom 1: the matrix is the sole source of scale.
      visual.style.zoom = `${1 / ancestorZoom}`;
      visual.style.top = '0';
      visual.style.left = '0';
      visual.style.transformOrigin = '0 0';
      // **Written now, not left to the first `moved()`.** A faithful lift puts
      // the visual at the viewport origin and encodes its entire position in
      // the matrix, so until something writes a transform the row paints in the
      // top-left corner at its untransformed size. The kernel activates *on* a
      // pointer sample and renders only from the next one, so that window is a
      // real frame whenever the pointer pauses or its samples coalesce.
      // Promotion has to be visually transparent on its own — the same reason
      // `neutralizeUA` re-asserts the authored UA properties. The flat branch
      // below needs no equivalent: it positions from `originRect` and its base
      // transform is empty.
      visual.style.transform = base;
    } else {
      if (ancestorZoom !== 1) {
        visual.style.zoom = `${1 / ancestorZoom}`;
      }

      visual.style.top = `${originRect.top + originRect.height / 2 - height / 2}px`;
      visual.style.left = `${originRect.left + originRect.width / 2 - width / 2}px`;
    }

    const topLayerDisposer = acquireTopLayer(visual, unwind);

    const session = makeSession(visual, base, null, () => {
      // `finally`, not sequence: restoring the inline styles is the one
      // guarantee this module owns outright, and a `hidePopover()` that throws
      // — or a prior-popover restoration that does — must not cost the visual
      // its authored `position`, `width` and `transform` permanently.
      try {
        topLayerDisposer();
      } finally {
        styleLeaseDisposer();
      }
    });

    return { session, inheritedSpace };
  } catch (error) {
    styleLeaseDisposer();
    throw error;
  }
}
/**
 * The FIFO run-to-completion action queue. Entirely kernel-private.
 *
 * Actions are stored as **two parallel arrays** rather than as entry objects,
 * so an enqueue is two pushes with no per-entry allocation. Array capacity
 * growth is amortized, so this is not literally allocation-free and is not
 * claimed to be.
 *
 * A nested dispatch appends to the live queue and returns; it never interrupts
 * the action already running. The outermost frame owns the pass and reaches the
 * appended entry in the same drain.
 *
 * The queue owns no semantics. Validation, transitions and effects belong to
 * the kernel's action handler, which must be **total**: an action it does not
 * recognise in the current phase is ignored, never thrown on.
 *
 * `drain` takes `handle` and `panic` as arguments so the kernel can hoist both
 * to one closure per controller, rather than allocating a fresh handler and
 * panic arrow on every outer dispatch.
 */

export type ActionQueue = {
  /** Pending action tags, FIFO. */
  actions: number[];
  /** Pending action arguments, positionally paired with {@link actions}. */
  args: unknown[];
  /** Whether a drain is already in progress on the stack. */
  running: boolean;
  /** Terminal latch. Once set, nothing is admitted and nothing is drained. */
  closed: boolean;
};

export function createActionQueue(): ActionQueue {
  return { actions: [], args: [], running: false, closed: false };
}

/**
 * Appends one action. Callers must have already rejected the closed case; this
 * is the hot path and does not re-check.
 */
export function enqueue(
  queue: ActionQueue,
  action: number,
  argument: unknown,
): void {
  queue.actions.push(action);
  queue.args.push(argument);
}

/**
 * Clears the queue and drops every retained argument, so a queued DOM element
 * or consumer value cannot outlive the drain that abandoned it.
 */
export function clearQueue(queue: ActionQueue): void {
  queue.actions.length = 0;
  queue.args.length = 0;
}

/**
 * Drains to completion, then clears. Re-entrant calls return immediately
 * because the outermost frame owns the drain and will reach the newly appended
 * work.
 *
 * A throw escaping `handle` is an invariant violation and goes to `panic`,
 * which must terminalize the controller.
 */
export function drain(
  queue: ActionQueue,
  handle: (action: number, argument: unknown) => void,
  panic: (error: unknown) => void,
): void {
  if (queue.running) {
    return;
  }

  queue.running = true;

  try {
    // `handle` can close the queue synchronously (a consumer callback calling
    // `destroy()`), so the terminal latch is re-read every iteration.
    // oxlint-disable-next-line no-unmodified-loop-condition
    for (let i = 0; !queue.closed && i < queue.actions.length; i += 1) {
      handle(queue.actions[i]!, queue.args[i]);
    }
  } catch (error) {
    panic(error);
  } finally {
    clearQueue(queue);
    queue.running = false;
  }
}
/**
 * One controller's owning DOM environment, derived from an element's
 * `ownerDocument` and its `defaultView`. Document listeners, scroll offsets,
 * animation frames, DOM constructors, and realm-sensitive type checks use this
 * value rather than ambient globals, so a controller created inside an iframe
 * behaves correctly.
 *
 * Construction fails explicitly when `defaultView` is `null`; falling back to
 * the ambient `window` would mix realms.
 *
 * `LandingContext` carries this value, so a custom landing runner receives the
 * realm it must schedule and measure in.
 */
export type DOMRealm = Readonly<{
  document: Document;
  window: Window & typeof globalThis;
  /** Structural check for an element belonging to this or any realm. */
  isElement(value: unknown): value is HTMLElement;
}>;

export function createRealm(element: Element): DOMRealm {
  const document = element.ownerDocument;
  const view = document.defaultView;

  if (!view) {
    throw new Error('drag: realm/no-owning-window');
  }

  return {
    document,
    window: view,
    isElement(value): value is HTMLElement {
      // This realm first. `instanceof` is exact where a bare `nodeType === 1`
      // test is not: that test accepts SVG and MathML elements, and any plain
      // object carrying the property, all of which the `HTMLElement` return
      // type claims they are not.
      if (value instanceof view.HTMLElement) {
        return true;
      }

      // Another realm's element is not `instanceof` *this* realm's constructor,
      // so reach that realm's constructor through the node's own document
      // rather than weakening the check to a duck-type.
      const foreign = (value as Node | null | undefined)?.ownerDocument
        ?.defaultView;

      return foreign != null && value instanceof foreign.HTMLElement;
    },
  };
}
/**
 * The transactional seam driver.
 *
 * Every substantial action is three stages — **prepare** (validation, pure
 * calculation, DOM reads, local acquisition), **commit** (short, effectively
 * non-throwing), **post-commit effects** (DOM writes, lifetime closes,
 * continuations, callbacks). The order is the shape of the contract rather than
 * a rule the behavior obeys: the kernel drives all three stages and the
 * behavior supplies two pure-ish callbacks.
 *
 * There is one core routine, and **no seam is only the core** — the discard
 * policy and the failure policy differ per seam, so each seam wraps the core
 * with its own.
 */
import { DraggableWarning, type Notify } from './errors.ts';
import type { FailureStage } from './failures.ts';
import type { Draft, Frame } from './frames.ts';

/**
 * A seam that stages nothing uses `Prepared = true` and returns the literal.
 *
 * `extends {}` excludes `null` and `undefined` while still admitting the `true`
 * sentinel, an element, or any object — which keeps `Prepared | null`
 * unambiguous as the discard signal without leaving it to prose.
 */
export type Transition<
  Part extends object,
  Prepared extends {} = true,
  Capability = void,
> = Readonly<{
  /**
   * Returns the staged value, or `null` to discard. Must not touch `current`,
   * must not perform DOM writes, and must keep every acquisition local —
   * everything it acquires travels out through `Prepared`.
   */
  prepare(draft: Draft<Part>, capability: Capability): Prepared | null;

  /**
   * Post-commit effects, for an already-published transition. A throw here
   * becomes a classified failure **from the committed state**; the transition
   * is not reverted.
   */
  effect(
    current: Readonly<Frame<Part>>,
    prepared: Prepared,
    capability: Capability,
  ): void;

  /**
   * Called instead of `effect` when the kernel discards a successful `prepare`
   * because a reentrant `cancel()` or `destroy()` invalidated it. Releases
   * whatever `prepare` staged. Publishes nothing, reports nothing.
   */
  rollback?(prepared: Prepared): void;
}>;

/**
 * Behavior action tags get the same envelope, which is what makes "the behavior
 * never calls `begin()`/`commit()`" hold for behavior-initiated work too.
 *
 * `Prepared` is opaque to the kernel, which threads it; the behavior narrows it
 * by tag.
 */
export type ActionTransition<Part extends object> = Readonly<{
  prepare(tag: number, argument: unknown, draft: Draft<Part>): {} | null;
  effect(
    tag: number,
    argument: unknown,
    current: Readonly<Frame<Part>>,
    prepared: {},
  ): void;
  rollback?(tag: number, prepared: {}): void;
}>;

/** `prepare` returned `null` — nothing happened. */
export const SEAM_DISCARDED = 0;
/** A reentrant cancel/destroy invalidated an otherwise good prepare. */
export const SEAM_INVALIDATED = 1;
/** Classified; nothing committed. */
export const SEAM_PREPARE_FAILED = 2;
/** Committed, effect returned normally. */
export const SEAM_COMMITTED = 3;
/** Classified, from the committed state. */
export const SEAM_EFFECT_FAILED = 4;

/**
 * What one seam run did, named once so every caller branches on the same
 * vocabulary.
 *
 * There are no predicate helpers over this union; call sites name the outcomes
 * they mean.
 *
 * **A classified failure must also stop incompatible continuation**, and the
 * driver is where that is enforced, because the failure checkpoint is *queued*.
 * Between the throw and the checkpoint there is a window in which the driver
 * would otherwise still be doing success work — so `SEAM_PREPARE_FAILED`
 * returns before `commit()`, and `SEAM_EFFECT_FAILED` returns before anything
 * is staged.
 */
export type SeamOutcome =
  | typeof SEAM_DISCARDED
  | typeof SEAM_INVALIDATED
  | typeof SEAM_PREPARE_FAILED
  | typeof SEAM_COMMITTED
  | typeof SEAM_EFFECT_FAILED;

/**
 * The kernel-private state the driver operates on. Supplied by `createKernel`,
 * which owns the frame pair, the operation identity and the queue.
 *
 * The frames are read through accessors because the kernel *swaps* the two
 * references at commit, so no stable reference can be captured here.
 */
export type SeamContext<Part extends object> = Readonly<{
  /** `Object.assign(draft, current)`. */
  begin(): void;
  /** Swap the two frame references. */
  commit(): void;
  /** False once a reentrant cancel or destroy invalidated the preparation. */
  preparationValid(): boolean;
  readCurrent(): Readonly<Frame<Part>>;
  readDraft(): Draft<Part>;
  /** Queue a classified failure against the operation the kernel holds. */
  fail(stage: FailureStage, error: unknown): void;
  /**
   * The controller's one channel. No checkpoint is queued, no recovery is
   * selected, and the operation's own outcome is untouched — which is what
   * makes everything the driver sends here a {@link DraggableWarning}.
   */
  notify: Notify;
}>;

export type SeamDriver<Part extends object> = Readonly<{
  /**
   * The shared core: begin → prepare → revalidate → rollback-or-commit →
   * effect. Returns the outcome; the caller applies its own seam's continuation
   * policy.
   *
   * A committed transition leaves its `Prepared` value in the driver's staging
   * slot, for the two seams whose staged value the *kernel* needs after the
   * seam returns — the release seam's `ResolutionCommand`, the settlement
   * seam's gate plan. Read it with {@link SeamDriver.consumeStaged}.
   *
   * `effectStage` defaults to `stage` and exists for the one seam whose two
   * phases fail at different stages: a behavior action resolves an insertion in
   * `prepare` and moves the placeholder in `effect`, and a throw in each is
   * classified at its own stage. An explicit `host.fail` narrows further from
   * the inside; this is only the default a raw throw lands on.
   */
  runCore<Prepared extends {}, Capability>(
    transition: Transition<Part, Prepared, Capability>,
    capability: Capability,
    stage: FailureStage,
    effectStage?: FailureStage,
  ): SeamOutcome;

  /**
   * Takes the staged value of the last committed transition, clearing the slot.
   *
   * **Consume-and-clear, and cleared again as every seam opens.** Both halves
   * are load-bearing: a staged value must never outlive the one transition that
   * produced it. Without the clear-on-read, a seam that commits without staging
   * anything would let a caller read the *previous* seam's command; without the
   * clear-on-open, so would a seam that discarded or failed. Either would
   * execute a resolution belonging to a transaction that is over.
   *
   * Returns `null` when the last seam staged nothing, discarded, was
   * invalidated, failed, or committed an effect that then abandoned the
   * operation.
   *
   * **Every seam either consumes its staged value or drops it.** The two seam
   * policies below drop it for their callers; the seams the kernel drives
   * directly drop it themselves. A value left behind is reported.
   */
  consumeStaged(): unknown;

  /**
   * A non-transactional seam returning nothing — `moved`, `finalized`. Returns
   * `false` when it threw or latched a failure.
   *
   * This exists so those seams behave **identically** whether the behavior
   * throws or calls `host.fail`. Without it a `moved` throw would escape the
   * handler and become a *panic* that destroyed the controller, contradicting
   * the existence of `FAILURE_RENDERER_WRITE`.
   */
  runLeaf(run: () => void, stage: FailureStage): boolean;

  /**
   * A non-transactional seam returning a value — `anchorTarget`. Returns
   * `undefined` when it threw or latched a failure, which is why `Value` is
   * constrained to exclude `undefined`.
   */
  runLeafValue<Value extends {}>(
    run: () => Value,
    stage: FailureStage,
  ): Value | undefined;

  /**
   * {@link SeamDriver.runLeafValue} on the **unclassified track**: the seam
   * still runs inside a phase — re-entry refused, `host.fail` latched, one
   * report per phase — but a failure reaches the consumer as a warning instead
   * of settling the operation.
   *
   * One caller: the arm-time landing measurement. A target that cannot be
   * produced and one that cannot be trusted are the same fault, and neither is
   * a reason to tell a consumer whose reorder succeeded that it did not.
   *
   * There is no stage argument: an unclassified failure names no stage, only a
   * `reason` the report carries.
   */
  runUnclassifiedValue<Value extends {}>(
    run: () => Value,
    reason: string,
  ): Value | undefined;

  /**
   * `host.fail`. Valid **only inside a kernel-driven seam of the current
   * operation**: a call outside one is reported as a warning instead, because a
   * late continuation from operation A could otherwise classify a failure
   * against operation B.
   */
  requestFailure(stage: FailureStage, error: unknown): void;

  /** Whether a seam phase is currently open. Diagnostics and tests. */
  isInSeam(): boolean;
}>;

/**
 * No phase is open. `FailureStage` starts at 1, so `0` and `-1` are free to
 * carry the two readings a stage alone cannot.
 */
const NO_STAGE = 0;

/**
 * The stage of a phase whose failures are **reported, never classified**.
 *
 * One sentinel, because there is one report channel.
 *
 * Two phases open under it, and their reasons are worth keeping distinct even
 * though their handling is now identical. `rollback` runs when the operation is
 * already invalid, so classifying there would open a transition against an
 * operation the kernel has just decided to abandon. The arm-time landing
 * measurement runs when the operation is already **committed**, so classifying
 * there would settle a drop that really happened. Applying the sentinel to the
 * whole phase is what makes an explicit `host.fail` inside either behave
 * exactly like a throw inside it.
 */
const UNCLASSIFIED = -1;

/** What an open phase classifies against. */
type PhaseStage = FailureStage | typeof UNCLASSIFIED;

/**
 * A phase that threw or latched a failure, as a value.
 *
 * A private symbol, so it is distinguishable from every legal `Prepared`,
 * `null` and leaf value without constraining what a seam may stage.
 */
const FAILED = Symbol();

export function createSeamDriver<Part extends object>(
  context: SeamContext<Part>,
): SeamDriver<Part> {
  /**
   * The stage the open phase classifies against, or `NO_STAGE` between phases.
   * One variable rather than a set of booleans: *whether* behavior code is
   * running, *which* operation stage owns its failures, and *whether* they are
   * classified at all are three readings of the same fact, and splitting them
   * let them drift apart.
   */
  let openStage: PhaseStage | typeof NO_STAGE = NO_STAGE;
  /**
   * Set by `requestFailure`, cleared as each phase opens. **A latched failure
   * is indistinguishable from a throw at the driver boundary** — which is the
   * whole point: enqueuing a checkpoint is not enough on its own, because the
   * checkpoint is queued and the window before it applies is exactly what the
   * latch closes.
   */
  let failureRequested = false;
  /**
   * The message an `UNCLASSIFIED` phase reports under. Set as that phase opens
   * and read only while it is open, which is the same lifetime
   * `failureRequested` has and for the same reason: the driver runs exactly one
   * phase at a time (`refuseReentry`).
   *
   * A string rather than a `FailureStage`: the warning names its reason in its
   * message, so the driver carries the reason rather than a classification it
   * is about to refuse to apply.
   */
  let unclassifiedReason = 'drag: seam/rollback-failed';
  /**
   * The staged value of the last committed transition. Owned by the driver
   * rather than passed in, so no call path can skip the reset: passed in, a
   * `runCore` handed no slot would leave the previous seam's value readable.
   */
  let staged: unknown = null;
  /**
   * Set when a seam is re-entered, and the reason the refusal is a latch rather
   * than a bare `throw`: the nested call raises from inside the outer seam's
   * `prepare` or `effect`, so the outer `catch` would otherwise classify an
   * invariant break as an ordinary behavior failure and swallow it.
   *
   * **This, and not what was thrown, is the whole decision** — which is what
   * makes it a latch rather than an error code. The driver never consults the
   * raised value, so behavior code that catches the refusal has caught nothing
   * it can act on and unwinds exactly as one that let it pass.
   */
  let reentry = false;

  /**
   * Refuses to open anything while a phase is already open, **before the caller
   * mutates a byte**.
   *
   * Strictly non-reentrant. Nothing in the kernel runs behavior code from
   * inside other behavior code — the queue is run-to-completion, so a nested
   * `dispatch` from a callback appends and returns, and the appended action
   * opens its phase only after this one has finished.
   *
   * **What `openStage` covers is the foreign-code window, and that is the
   * boundary this guard is for.** It is set as a phase opens and cleared before
   * `runPhase` classifies, so a phase opened from the classification path would
   * not be refused. Read the sentinel as *is foreign code on the stack*, which
   * is where a nested call can originate; it is not a general nesting
   * interlock.
   *
   * **Consumer code still runs past the clear, and the queue is what covers
   * it**: `context.notify` reaches the consumer's `onError`, and a `dispatch`
   * from there appends because `drain` returns while `queue.running`.
   * `context.fail` enqueuing covers only the classification this module
   * performs, which is the smaller half.
   *
   * A violation is an invariant break, not a recoverable condition — and the
   * break is **a lifecycle the kernel reports as performed and did not
   * perform**. The frames swap an even number of times, so nested from
   * `prepare` **neither** transaction lands and `current` is untouched, and
   * nested from `effect` the outer's committed frame is **replaced wholesale**
   * by the inner's while the staged command run against it is the outer's. Both
   * seams then return `SEAM_COMMITTED`, and neither path produces a diagnostic,
   * which is the worst shape a broken invariant can take: the code succeeds and
   * does the wrong thing. A nested `begin()` does **not** publish a half-built
   * frame — the swaps cancel — so that is not the reason to refuse.
   *
   * So the refusal **latches** rather than merely throwing — the nested call
   * raises from inside the outer phase, whose `catch` would otherwise classify
   * an invariant break as an ordinary behavior failure and swallow it.
   * `runPhase` rethrows past every classification on the way out to reach the
   * queue's panic path, which is also what makes behavior code that catches its
   * own refusal panic anyway.
   */
  const refuseReentry = (): void => {
    if (openStage !== NO_STAGE) {
      reentry = true;
      // **`null`, and deliberately.** Not an `Error`, because an `Error`
      // carries a message and a message here would be an identity for a
      // condition no consumer can reach; `null` in particular because the value
      // lands on `DraggableError.cause`, where a consumer's ordinary handling
      // meets it — a symbol there throws on interpolation, and there genuinely
      // is no cause on this path.
      // oxlint-disable-next-line typescript/only-throw-error
      throw null;
    }
  };

  /**
   * One behavior callback, start to finish — **the only place this module runs
   * foreign code**, and therefore the one boundary the re-entry guard has to
   * cover. Refuses a nested phase, opens the phase, runs `run`, closes it,
   * panics on a latched re-entry, and reduces a throw or a latched `host.fail`
   * to {@link FAILED}. Returns whatever `run` returned otherwise.
   *
   * The order is the contract, and having it in one place is why it holds for
   * every seam: **refuse, then close, then panic, then classify**. The panic
   * has to escape past the classification, so it cannot live inside the `catch`
   * that classifies — a `throw` there would be caught by that very handler.
   * Hence the caught error is carried out as a value and re-examined below.
   */
  const runPhase = <Value>(
    stage: PhaseStage,
    run: () => Value,
  ): Value | typeof FAILED => {
    refuseReentry();
    failureRequested = false;
    openStage = stage;

    let value: Value | typeof FAILED;
    let raised: unknown;

    try {
      value = run();
    } catch (error) {
      value = FAILED;
      raised = error;
    }

    openStage = NO_STAGE;

    if (reentry) {
      // Cleared on the way out: exactly one `runCore` on the stack got past the
      // guard, and it is the one that unlatches. The raised value is not
      // consulted — `reentry` is the whole decision, so a phase that swallowed
      // the throw unwinds here exactly as one that let it pass.
      reentry = false;
      // oxlint-disable-next-line typescript/only-throw-error
      throw null;
    }

    if (value === FAILED) {
      // **One phase, one classification**, and the two arms below are the two
      // ways a phase can produce a fault the kernel refuses to classify: the
      // phase was never classified at all, or it was already classified once.
      // Classifying a second time for a single phase would let the later error
      // decide the operation's outcome. Nothing is lost either way: both arms
      // reach the same consumer the classified one does.
      if (stage === UNCLASSIFIED) {
        // `unclassifiedReason` rather than the sentinel, because the sentinel
        // says how the failure travels and never what it was — the reason the
        // consumer reads is the one the caller named.
        context.notify(
          new DraggableWarning(unclassifiedReason, { cause: raised }),
        );
      } else if (failureRequested) {
        // **One phase, one report.** A phase that called `host.fail` and then
        // threw is already classified against its own error; the throw travels
        // as a warning, which is what keeps it from deciding the outcome.
        context.notify(
          new DraggableWarning('drag: seam/failed-then-threw', {
            cause: raised,
          }),
        );
      } else {
        context.fail(stage, raised);
      }

      return FAILED;
    }

    return failureRequested ? FAILED : value;
  };

  return {
    runCore(transition, capability, stage, effectStage = stage) {
      // Not the same call as the one inside `runPhase`, and not redundant with
      // it: a transaction mutates kernel state *before* its first phase opens,
      // and `begin()` would rebuild the draft the outer seam is still building.
      // The refusal has to land before that, not one line later.
      refuseReentry();

      if (staged !== null) {
        // The clear below already makes this harmless; the report is what stops
        // it from being *invisible*. A staged value still sitting here means
        // the previous seam neither consumed nor dropped it, which is the one
        // way a command can outlive its transaction.
        context.notify(new DraggableWarning('drag: seam/staged-unconsumed'));
      }

      staged = null;
      context.begin();

      const prepared = runPhase(stage, () =>
        transition.prepare(context.readDraft(), capability),
      );

      if (prepared === FAILED) {
        return SEAM_PREPARE_FAILED; // nothing staged escaped
      }

      if (prepared === null) {
        return SEAM_DISCARDED; // the draft is abandoned
      }

      if (!context.preparationValid()) {
        unclassifiedReason = 'drag: seam/rollback-failed';
        runPhase(UNCLASSIFIED, () => transition.rollback?.(prepared));
        return SEAM_INVALIDATED;
      }

      context.commit();

      const effected = runPhase(effectStage, () =>
        transition.effect(context.readCurrent(), prepared, capability),
      );

      if (effected === FAILED) {
        return SEAM_EFFECT_FAILED; // classified, from the committed state
      }

      // Staged **after** the effect, deliberately. Anything the effect triggers
      // — a queued action, a consumer callback — therefore cannot observe or
      // clear this transition's staged value, and the assignment lands last
      // regardless of what ran in between.
      //
      // Which is exactly why it is conditional. Staging last means staging
      // *after* an effect that reentrantly destroyed the controller or
      // abandoned the operation, and the caller would then execute a command
      // belonging to a transaction that no longer has anything to execute
      // against — the release seam invoking the consumer's resolver for an
      // operation `destroy()` already retired. A preparation that is no longer
      // valid stages nothing, and the caller reads `null`.
      staged = context.preparationValid() ? prepared : null;
      return SEAM_COMMITTED;
    },

    runLeaf(run, stage) {
      return runPhase(stage, run) !== FAILED;
    },

    runLeafValue(run, stage) {
      const value = runPhase(stage, run);

      return value === FAILED ? undefined : value;
    },

    runUnclassifiedValue(run, reason) {
      unclassifiedReason = reason;

      const value = runPhase(UNCLASSIFIED, run);

      return value === FAILED ? undefined : value;
    },

    consumeStaged() {
      const value = staged;

      staged = null;
      return value;
    },

    requestFailure(stage, error) {
      // **A latched failure and a throw are the same event on this path too.**
      // The flag is what makes `runPhase` return `FAILED` for a phase that
      // latched without throwing, so the caller sees no target either way.
      if (openStage === UNCLASSIFIED) {
        failureRequested = true;
        context.notify(
          new DraggableWarning(unclassifiedReason, { cause: error }),
        );
        return;
      }

      if (openStage === NO_STAGE) {
        // **One warning, not two reports.** A caught error and a
        // library-authored companion naming why the classification was denied
        // are one fault said twice: the message names the reason and `cause`
        // carries the caller's error, which is what a discriminating code would
        // otherwise be for.
        //
        // The caller's `stage` is deliberately discarded. It describes a
        // classification the kernel has just refused to apply, and carrying it
        // into the warning would publish a claim about the operation that this
        // branch exists to *not* make.
        context.notify(
          new DraggableWarning('drag: seam/fail-outside-seam', {
            cause: error,
          }),
        );

        return;
      }

      // The stage is the caller's, not the open phase's: a leaf narrows its own
      // stage from the inside (`moved` renders and schedules in one callback).
      failureRequested = true;
      context.fail(stage, error);
    },

    isInSeam: () => openStage !== NO_STAGE,
  };
}

/**
 * The activation seam's policy.
 *
 * A discard **retires the operation** — the kernel releases capture, disposes
 * the lift and returns to `IDLE`; there is no such thing as a pending operation
 * with no presentation. A *failure* does **not** retire: the operation stays
 * live for its queued checkpoint, because retiring would make that entry stale
 * and `onError` might never fire.
 *
 * On a committed activation the kernel re-checks `preparationValid()` before
 * dispatching `START_COMMITTED`, since `activation.effect` invokes `onStart`
 * last and that callback may cancel or destroy.
 */
export function runActivationSeam<
  Part extends object,
  Prepared extends {},
  Capability,
>(
  driver: SeamDriver<Part>,
  transition: Transition<Part, Prepared, Capability>,
  capability: Capability,
  stage: FailureStage,
  policy: Readonly<{ retire(): void; committed(): void }>,
): SeamOutcome {
  const outcome = driver.runCore(transition, capability, stage);

  // Dropped **before** the policy runs, so nothing this seam triggers can read
  // the placeholder it staged. Activation's staged value is consumed by its own
  // `effect` and has no reader afterwards — whatever it is: the behavior
  // chooses the staged type, and the kernel does nothing with it but hand it
  // back and drop it.
  driver.consumeStaged();

  if (outcome === SEAM_DISCARDED || outcome === SEAM_INVALIDATED) {
    policy.retire();
  } else if (outcome === SEAM_COMMITTED) {
    policy.committed();
  }

  return outcome;
}

/**
 * The release seam's policy.
 *
 * Release **cannot discard** — `prepare` returns a command or a rejection, and
 * motion is already closed, so "changed my mind" has no meaning. The staged
 * command is executed **only** on a committed transition: running it
 * unconditionally would let the consumer receive `onReorder` for a release
 * whose presentation effect had thrown, racing the failure through the same
 * queue.
 */
export function runReleaseSeam<Part extends object, Prepared extends {}>(
  driver: SeamDriver<Part>,
  transition: Transition<Part, Prepared>,
  stage: FailureStage,
  execute: (prepared: Prepared) => void,
): SeamOutcome {
  const outcome = driver.runCore(transition, undefined, stage);
  // Taken unconditionally: on any other outcome this clears whatever an earlier
  // seam left, and `execute` never sees it.
  const command = driver.consumeStaged();

  // `null` on a committed seam means the effect abandoned the operation — a
  // reentrant `destroy()`. The command has nothing left to run against, and
  // executing it would open the consumer round-trip for a retired operation.
  if (outcome === SEAM_COMMITTED && command !== null) {
    execute(command as Prepared);
  }

  return outcome;
}
/**
 * **The unwind must be total.**
 *
 * **This module is named for the rule it expresses, not for a destination.**
 * Routing an error to the consumer and letting the caller continue are two
 * separate jobs; only the second one is here, and it is a lifecycle rule rather
 * than a reporting one.
 *
 * The rule at every site is the same sentence: **the statement after this call
 * is load-bearing.** Another resource to release, another teardown step, or the
 * original error to rethrow. Ten of the sites are literal multi-resource
 * releases, three of them `for` loops over installer disposers or an undo
 * ledger. Unwrapped, a throw from step *n* skips steps *n+1* onward — which is
 * exactly how `destroy()` stops being terminal.
 *
 * The catch reports a {@link DraggableWarning} rather than an error, because an
 * unwind step that failed is by construction not consequential — the
 * operation's terminal result, phase sequence and settlement are already
 * decided by the time anything unwinds.
 */
import { DraggableWarning, type Notify } from './errors.ts';

/**
 * Runs one unwind step, absorbing a throw so the next one still runs. Returns
 * `undefined` when the step failed.
 */
export type Unwind = <T>(step: () => T) => T | undefined;

/**
 * Builds the unwind guard over one controller's channel.
 *
 * A closure per kernel rather than a free function taking the notifier: the
 * fourteen call sites read `unwind(fn)` either way, and threading the notifier
 * through each of them would put the channel's identity at every site that
 * merely wants to survive a throw.
 *
 * **The notifier must not throw** — the channel's own guard is what guarantees
 * that, and it is why this function needs no `try` around the report. Every
 * site here is already inside a teardown whose next step matters; a second
 * failure mode in the reporting path would defeat the one property this exists
 * to provide.
 */
export function createUnwind(notify: Notify): Unwind {
  return (step) => {
    try {
      return step();
    } catch (error) {
      // One message for every site, and `cause` carries what was caught. The
      // sites differ in *which* resource failed to release and not in what the
      // consumer can do about it, so a discriminating code would serve nothing.
      notify(
        new DraggableWarning('drag: unwind/step-failed', { cause: error }),
      );
      return undefined;
    }
  };
}
