  snapshot: CollectionSnapshot,
  item: HTMLElement,
  direction: KeyboardDirection,
): Insertion | null {
  const { items } = snapshot;
  const from = items.indexOf(item);

  if (from === -1) {
    return null;
  }

  const up = direction === DIRECTION_UP;

  if (up ? from === 0 : from === items.length - 1) {
    return null; // already at that edge
